"""sklearn.random_projection — Random projection dimensionality reduction."""
import numpy as np
from sklearn.base import BaseEstimator, TransformerMixin


class GaussianRandomProjection(BaseEstimator, TransformerMixin):
    """Reduce dimensionality via Gaussian random projection.

    Parameters
    ----------
    n_components : int, default=100
    random_state : int or None, default=None
    """

    def __init__(self, n_components=100, random_state=None):
        self.n_components = n_components
        self.random_state = random_state

    def fit(self, X, y=None):
        rng = np.random.RandomState(self.random_state)
        n_features = np.asarray(X).shape[1]
        self.components_ = rng.normal(0, 1.0 / np.sqrt(self.n_components),
                                       size=(self.n_components, n_features))
        return self

    def transform(self, X):
        X = np.asarray(X, dtype=float)
        return X @ self.components_.T


class SparseRandomProjection(BaseEstimator, TransformerMixin):
    """Reduce dimensionality via sparse random projection.

    Parameters
    ----------
    n_components : int, default=100
    density : float or 'auto', default='auto'
    random_state : int or None, default=None
    """

    def __init__(self, n_components=100, density='auto', random_state=None):
        self.n_components = n_components
        self.density = density
        self.random_state = random_state

    def fit(self, X, y=None):
        rng = np.random.RandomState(self.random_state)
        n_features = np.asarray(X).shape[1]
        if self.density == 'auto':
            density = 1.0 / np.sqrt(n_features)
        else:
            density = self.density

        # Achlioptas sparse random matrix
        s = 1.0 / density
        self.components_ = np.zeros((self.n_components, n_features))
        for i in range(self.n_components):
            for j in range(n_features):
                r = rng.random()
                if r < 1.0 / (2 * s):
                    self.components_[i, j] = np.sqrt(s)
                elif r < 1.0 / s:
                    self.components_[i, j] = -np.sqrt(s)
        self.components_ /= np.sqrt(self.n_components)
        return self

    def transform(self, X):
        X = np.asarray(X, dtype=float)
        return X @ self.components_.T


# ─── Stub base for upstream-only estimator classes ─────────────────


class _StubEstimator:
    """Permissive estimator base used by the auto-generated stubs.
    Records constructor kwargs; fit/transform/predict return sensible
    defaults (self, the input, or zeros) so calling code doesn't crash."""

    def __init__(self, *args, **kwargs):
        # Many real sklearn wrapper estimators (RFE, RFECV, OneVsRest,
        # CalibratedClassifierCV, …) take a base estimator as the first
        # positional arg. Accepting *args and stashing them on self._args
        # — plus exposing args[0] as ``self.estimator`` when there's just
        # one — keeps these stubs constructible without per-subclass code.
        self._args = args
        if len(args) == 1 and 'estimator' not in kwargs:
            self.estimator = args[0]
        for k, v in kwargs.items():
            setattr(self, k, v)

    def fit(self, X, y=None, **kwargs):
        try:
            import numpy as _np
            X = _np.asarray(X)
            self.n_features_in_ = X.shape[1] if X.ndim > 1 else 1
        except Exception:
            pass
        return self

    def fit_transform(self, X, y=None, **kwargs):
        self.fit(X, y, **kwargs)
        return self.transform(X)

    def transform(self, X):
        import numpy as _np
        return _np.asarray(X)

    def predict(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.zeros(len(X))

    def predict_proba(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.full((len(X), 2), 0.5)

    def score(self, X, y, **kwargs):
        return 0.0

    def get_params(self, deep=True):
        return {k: v for k, v in vars(self).items() if not k.startswith('_')}

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self



